// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierStateArena;
import org.junit.jupiter.api.Test;

class LmdbFrontierLongObjectMemoTest {

	@Test
	void retainsExactPrimitiveKeysWithoutEscapingArenaBudget() {
		try (FrontierStateArena arena = new FrontierStateArena(16 * 1024L);
				LmdbFrontierLongObjectMemo<Object> memo = new LmdbFrontierLongObjectMemo<>(arena)) {
			Object first = new Object();
			Object second = new Object();

			assertNull(memo.get(41L));
			memo.put(41L, first);
			memo.put(73L, second);

			assertSame(first, memo.get(41L));
			assertSame(second, memo.get(73L));
			assertEquals(2, memo.size());
			assertEquals(memo.retainedBytes(), arena.temporaryReservedBytes() - 48L);
		}
	}

	@Test
	void memoryExhaustionOnlyDeclinesNewMemoEntries() {
		try (FrontierStateArena arena = new FrontierStateArena(4_096L);
				LmdbFrontierLongObjectMemo<String> memo = new LmdbFrontierLongObjectMemo<>(arena)) {
			for (long key = 1L; key <= 1_000L; key++) {
				memo.put(key, "value-" + key);
			}

			assertEquals("value-1", memo.get(1L));
			assertNull(memo.get(1_000L));
		}
	}
}
